              "col2": "<div title=\"string\" style=\"display: inline !important; white-space: nowrap !important; height: 20px;\"><span style=\"vertical-align: middle;\"><img src='images/icon_119.png' width='16' height='16' title='' style=\"vertical-align: bottom;\"></span> string</div></br>",
              "col3": "0..1 </br>",
