              "col1": "<div title=\"Event\" style=\"display: inline !important; white-space: nowrap !important; height: 20px;\"><a href=\"\" target=\"_blank\" onclick=\"navigate('Structure__EAID_ED83840A_A210_4afb_B987_376C88EC8B17');return false;\"><span style=\"vertical-align: middle;\"><img src='images/icon_123.png' width='16' height='16' title='' style=\"vertical-align: bottom;\"></span><a> <a href=\"\" target=\"_blank\" onclick=\"navigate('Structure__EAID_ED83840A_A210_4afb_B987_376C88EC8B17');return false;\">Event<a></div>"
