              "col1": "<div title=\"isUnavailable : boolean\" style=\"display: inline !important; white-space: nowrap !important; height: 20px;\"><span style=\"vertical-align: middle;\"><img src='images/icon_147.png' width='16' height='16' title='' style=\"vertical-align: bottom;\"></span> isUnavailable : boolean</div></br>",
