              "col1": "<div title=\"madeForDataItem : DataItem\" style=\"display: inline !important; white-space: nowrap !important; height: 20px;\"><span style=\"vertical-align: middle;\"><img src='images/icon_151.png' width='16' height='16' title='' style=\"vertical-align: bottom;\"></span> madeForDataItem : DataItem</div></br>",
              "col2": "<div title=\"DataItem\" style=\"display: inline !important; white-space: nowrap !important; height: 20px;\"><a href=\"\" target=\"_blank\" onclick=\"navigate('Structure__EAID_002C94B7_1257_49be_8EAA_CE7FCD7AFF8A');return false;\"><span style=\"vertical-align: middle;\"><img src='images/icon_145.png' width='16' height='16' title='' style=\"vertical-align: bottom;\"></span><a> <a href=\"\" target=\"_blank\" onclick=\"navigate('Structure__EAID_002C94B7_1257_49be_8EAA_CE7FCD7AFF8A');return false;\">DataItem<a></div></br>",
              "col3": "1 </br>",
