              "col0": 5,
              "col1": "<span style=\"vertical-align: middle;\"><img src='images/enum_literal_icon.png' width='16' height='16' title='' style=\"vertical-align: bottom;\"></span>&nbsp;MEASURED",
              "col2": "1.2",
              "col3": null,
              "col4": null,
              "col5": "tool has been measured."
